export const CUES = [{"t": 3.6, "end": 11.42, "lines": [{"t0": 3.6, "t1": 8.34, "text": "For millions of years, our ancestors lived as other animals do:"}, {"t0": 8.34, "t1": 12.02, "text": "when the sun went down, the day was over."}]}, {"t": 12.6, "end": 16.28, "lines": [{"t0": 12.6, "t1": 16.88, "text": "Then someone, somewhere, learned to keep a fire alive."}]}, {"t": 29.6, "end": 40.23, "lines": [{"t0": 29.6, "t1": 32.35, "text": "No one knows who, or when."}, {"t0": 32.21, "t1": 37.06, "text": "Burnt bone in a South African cave hints at fire a million years ago,"}, {"t0": 37.06, "t1": 40.83, "text": "though everyday use may have come much later."}]}, {"t": 47.6, "end": 52.31, "lines": [{"t0": 47.6, "t1": 49.75, "text": "Either way, for the first time,"}, {"t0": 49.75, "t1": 52.91, "text": "the day did not end when the sun did."}]}, {"t": 56.0, "end": 63.05, "lines": [{"t0": 56.0, "t1": 59.95, "text": "The oldest fossils of our own species, found in Morocco,"}, {"t0": 59.95, "t1": 63.65, "text": "are around three hundred thousand years old."}]}, {"t": 64.4, "end": 75.29, "lines": [{"t0": 64.4, "t1": 71.79, "text": "From Africa, people spread across the world: by sea to Australia at least fifty thousand years ago,"}, {"t0": 71.79, "t1": 75.89, "text": "and into the Americas before the Ice Age ended."}]}, {"t": 78.4, "end": 88.98, "lines": [{"t0": 78.4, "t1": 80.52, "text": "On a cave wall in Indonesia,"}, {"t0": 80.52, "t1": 86.8, "text": "someone left the outline of a hand at least sixty-seven thousand years ago."}, {"t0": 86.66, "t1": 89.58, "text": "It is the oldest cave art we know."}]}, {"t": 92.6, "end": 100.12, "lines": [{"t0": 92.6, "t1": 95.58, "text": "Starting around eleven thousand years ago,"}, {"t0": 95.58, "t1": 100.72, "text": "in several parts of the world, separately, people began to farm."}]}, {"t": 101.6, "end": 113.85, "lines": [{"t0": 101.6, "t1": 104.72, "text": "Wheat and barley in the Middle East."}, {"t0": 104.58, "t1": 107.47, "text": "Rice and millet in China."}, {"t0": 107.33, "t1": 109.66, "text": "Maize in Mexico."}, {"t0": 109.52, "t1": 112.31, "text": "Potatoes in the Andes."}, {"t0": 112.17, "t1": 114.45, "text": "Sorghum in Africa."}]}, {"t": 115.4, "end": 120.79, "lines": [{"t0": 115.4, "t1": 117.43, "text": "It was hard work."}, {"t0": 117.29, "t1": 121.39, "text": "But a field can feed far more people than a forest."}]}, {"t": 122.6, "end": 126.53, "lines": [{"t0": 122.6, "t1": 127.13, "text": "Villages became towns, and towns became cities."}]}, {"t": 127.4, "end": 134.24, "lines": [{"t0": 127.4, "t1": 131.23, "text": "Five thousand years ago, Uruk, in what is now Iraq,"}, {"t0": 131.23, "t1": 134.84, "text": "was home to tens of thousands of people."}]}, {"t": 137.0, "end": 139.32, "lines": [{"t0": 137.0, "t1": 139.92, "text": "And here, people began to write."}]}, {"t": 145.0, "end": 151.86, "lines": [{"t0": 145.0, "t1": 148.06, "text": "The first writing wasn't poetry."}, {"t0": 147.92, "t1": 152.46, "text": "It was accounts: barley, beer, sheep, and who owed what."}]}, {"t": 152.8, "end": 160.19, "lines": [{"t0": 152.8, "t1": 156.17, "text": "Writing was invented at least three times,"}, {"t0": 156.17, "t1": 160.79, "text": "independently: here, in China, and in Mesoamerica."}]}, {"t": 161.6, "end": 166.95, "lines": [{"t0": 161.6, "t1": 165.67, "text": "At about the same time, someone made the first wheel."}, {"t0": 165.53, "t1": 167.55, "text": "We don't know who."}]}, {"t": 170.6, "end": 178.6, "lines": [{"t0": 170.6, "t1": 176.34, "text": "Empires rose and fell, and roads and sea lanes carried silk and spices,"}, {"t0": 176.34, "t1": 179.2, "text": "horses and glass, and ideas."}]}, {"t": 179.4, "end": 191.67, "lines": [{"t0": 179.4, "t1": 183.1, "text": "Buddhism travelled from India to China."}, {"t0": 182.96, "t1": 186.25, "text": "Paper went from China to Baghdad."}, {"t0": 186.11, "t1": 189.2, "text": "And the numerals we still use, born in India,"}, {"t0": 189.2, "t1": 192.27, "text": "reached Europe through Arabic books."}]}, {"t": 194.6, "end": 204.62, "lines": [{"t0": 194.6, "t1": 196.33, "text": "Far out in the Pacific,"}, {"t0": 196.33, "t1": 205.22, "text": "navigators reading the stars and the swell found and settled almost every island in the widest ocean on Earth."}]}, {"t": 207.6, "end": 219.5, "lines": [{"t0": 207.6, "t1": 212.91, "text": "Printing began in China, and movable type in China and Korea."}, {"t0": 212.77, "t1": 214.71, "text": "In Europe, around 1450,"}, {"t0": 214.71, "t1": 220.1, "text": "Gutenberg's press met an alphabet of a few dozen letters."}]}, {"t": 221.0, "end": 224.63, "lines": [{"t0": 221.0, "t1": 223.1, "text": "Books multiplied."}, {"t0": 222.96, "t1": 225.23, "text": "So did arguments."}]}, {"t": 226.4, "end": 233.32, "lines": [{"t0": 226.4, "t1": 230.2, "text": "In 1492, European ships reached the Americas,"}, {"t0": 230.2, "t1": 233.92, "text": "and two halves of the world collided."}]}, {"t": 234.6, "end": 249.59, "lines": [{"t0": 234.6, "t1": 239.09, "text": "Maize and potatoes went on to feed much of the world."}, {"t0": 238.95, "t1": 244.3, "text": "But diseases from Europe killed a large share of the people of the Americas,"}, {"t0": 244.3, "t1": 250.19, "text": "and over twelve million Africans were forced across the Atlantic in chains."}]}, {"t": 252.4, "end": 259.03, "lines": [{"t0": 252.4, "t1": 256.45, "text": "In 1610, Galileo turned a telescope on Jupiter,"}, {"t0": 256.45, "t1": 259.63, "text": "and saw moons going around it."}]}, {"t": 260.4, "end": 266.04, "lines": [{"t0": 260.4, "t1": 263.29, "text": "Science was a new habit: look carefully,"}, {"t0": 263.29, "t1": 266.64, "text": "test the idea, and trust the evidence."}]}, {"t": 268.6, "end": 275.33, "lines": [{"t0": 268.6, "t1": 271.68, "text": "Then steam engines turned coal into motion,"}, {"t0": 271.68, "t1": 275.93, "text": "and factories and railways spread across the world."}]}, {"t": 276.6, "end": 290.34, "lines": [{"t0": 276.6, "t1": 281.6, "text": "With them, and with medicine, ordinary lives began to change."}, {"t0": 281.46, "t1": 282.12, "text": "In 1800,"}, {"t0": 282.12, "t1": 287.62, "text": "more than four in ten children died before the age of five."}, {"t0": 287.48, "t1": 290.94, "text": "Today, fewer than one in twenty do."}]}, {"t": 294.6, "end": 296.55, "lines": [{"t0": 294.6, "t1": 297.15, "text": "And then, the night changed."}]}, {"t": 308.2, "end": 315.2, "lines": [{"t0": 308.2, "t1": 310.06, "text": "Electricity."}, {"t0": 309.92, "t1": 312.07, "text": "Light at the flick of a switch,"}, {"t0": 312.07, "t1": 315.8, "text": "and power carried by wire to almost anywhere."}]}, {"t": 318.0, "end": 326.45, "lines": [{"t0": 318.0, "t1": 323.02, "text": "In 1903, a powered aeroplane flew for twelve seconds."}, {"t0": 322.88, "t1": 327.05, "text": "Sixty-six years later, people walked on the Moon."}]}, {"t": 329.0, "end": 336.72, "lines": [{"t0": 329.0, "t1": 334.4, "text": "Today, most of the eight billion people alive carry a computer in their pocket,"}, {"t0": 334.4, "t1": 337.32, "text": "connected to nearly everyone else."}]}, {"t": 342.0, "end": 344.43, "lines": [{"t0": 342.0, "t1": 345.03, "text": "And that is everything, so far."}]}, {"t": 349.6, "end": 354.28, "lines": [{"t0": 349.6, "t1": 352.53, "text": "Ahead, the cardboard is still blank."}, {"t0": 352.39, "t1": 354.88, "text": "No one has cut it yet."}]}, {"t": 357.8, "end": 359.43, "lines": [{"t0": 357.8, "t1": 360.03, "text": "That part is up to us."}]}];
